mapper.select:
/* Attd08Mapper.selectAttdLists */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT A.ATTD_ID AS attdId , A.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , A.NODE_CD AS nodeCd , NT.NODE_NM AS nodeNm , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq
/* schedule (1st / 2nd block) */ , SCH.SCH_TYPE AS schType , SCH.FST_SCH_STR_TIME AS plan1Start , SCH.FST_SCH_END_TIME AS plan1End , SCH.FST_SCH_BRK_MIN AS plan1BreakMin , SCH.SEC_SCH_STR_TIME AS plan2Start , SCH.SEC_SCH_END_TIME AS plan2End , SCH.SEC_SCH_BRK_MIN AS plan2BreakMin
/* actual 1st */ , A1.CHECK_IN_DATE AS act1InDate , A1.CHECK_IN_TIME AS act1InTime , A1.CHECK_IN_METHOD AS act1InMethod , A1.CHECK_OUT_DATE AS act1OutDate , A1.CHECK_OUT_TIME AS act1OutTime , A1.CHECK_OUT_METHOD AS act1OutMethod
/* actual 2nd */ , A2.CHECK_IN_DATE AS act2InDate , A2.CHECK_IN_TIME AS act2InTime , A2.CHECK_IN_METHOD AS act2InMethod , A2.CHECK_OUT_DATE AS act2OutDate , A2.CHECK_OUT_TIME AS act2OutTime , A2.CHECK_OUT_METHOD AS act2OutMethod
/* normalized times */ , FNC_STD_TIME( A1.CHECK_IN_TIME , IFNULL( CASE WHEN CHAR_LENGTH(FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKIN', A1.CHECK_IN_DATE, NULL)) = 0 THEN NULL ELSE FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKIN', A1.CHECK_IN_DATE, NULL) END , 0) , 'IN' ) AS act1InStdTime , FNC_STD_TIME( A1.CHECK_OUT_TIME , IFNULL( CASE WHEN CHAR_LENGTH(FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKOUT', A1.CHECK_OUT_DATE, NULL)) = 0 THEN NULL ELSE FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKOUT', A1.CHECK_OUT_DATE, NULL) END , 0) , 'OUT' ) AS act1OutStdTime , FNC_STD_TIME( A2.CHECK_IN_TIME , IFNULL( CASE WHEN CHAR_LENGTH(FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKIN', A2.CHECK_IN_DATE, NULL)) = 0 THEN NULL ELSE FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKIN', A2.CHECK_IN_DATE, NULL) END , 0) , 'IN' ) AS act2InStdTime , FNC_STD_TIME( A2.CHECK_OUT_TIME , IFNULL( CASE WHEN CHAR_LENGTH(FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKOUT', A2.CHECK_OUT_DATE, NULL)) = 0 THEN NULL ELSE FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'ATTD_STD_CHKOUT', A2.CHECK_OUT_DATE, NULL) END , 0) , 'OUT' ) AS act2OutStdTime
/* outside detection - any GPS row exists for this ATTD */ , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_ATTD_GPS G WHERE G.CMPNY_CD = A.CMPNY_CD AND G.ATTD_ID = A.ATTD_ID ) THEN 'Y' ELSE 'N' END AS isOutsideYn
/* status: schedule vs actual (HHmm string compare) */ , CASE WHEN A.CHECK_IN_TIME IS NULL OR A.CHECK_IN_TIME = '' THEN 'ABSENT' WHEN A.WORK_SEQ = 1 AND SCH.FST_SCH_STR_TIME IS NOT NULL AND A.CHECK_IN_TIME > SCH.FST_SCH_STR_TIME THEN 'LATE' WHEN A.WORK_SEQ = 2 AND SCH.SEC_SCH_STR_TIME IS NOT NULL AND A.CHECK_IN_TIME > SCH.SEC_SCH_STR_TIME THEN 'LATE' WHEN A.WORK_SEQ = 1 AND SCH.FST_SCH_END_TIME IS NOT NULL AND A.CHECK_OUT_TIME IS NOT NULL AND A.CHECK_OUT_TIME != '' AND A.CHECK_OUT_TIME < SCH.FST_SCH_END_TIME THEN 'EARLY_LEAVE' WHEN A.WORK_SEQ = 2 AND SCH.SEC_SCH_END_TIME IS NOT NULL AND A.CHECK_OUT_TIME IS NOT NULL AND A.CHECK_OUT_TIME != '' AND A.CHECK_OUT_TIME < SCH.SEC_SCH_END_TIME THEN 'EARLY_LEAVE' ELSE 'NORMAL' END AS attdStatusCd
FROM TB_USER_ATTD_MGMT A INNER JOIN node_tree NT ON A.CMPNY_CD = NT.CMPNY_CD AND A.SITE_CD = NT.SITE_CD AND A.NODE_CD = NT.NODE_CD INNER JOIN TB_USER U ON A.CMPNY_CD = U.CMPNY_CD AND A.USER_CD = U.USER_CD
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
LEFT JOIN TB_SCH_MGMT SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD AND SCH.USE_YN = 'Y'
LEFT JOIN TB_USER_ATTD_MGMT A1 ON A1.CMPNY_CD = A.CMPNY_CD AND A1.SITE_CD = A.SITE_CD AND A1.USER_CD = A.USER_CD AND A1.WORK_YMD = A.WORK_YMD AND A1.WORK_SEQ = 1 AND A1.DEL_YN = 'N'
LEFT JOIN TB_USER_ATTD_MGMT A2 ON A2.CMPNY_CD = A.CMPNY_CD AND A2.SITE_CD = A.SITE_CD AND A2.USER_CD = A.USER_CD AND A2.WORK_YMD = A.WORK_YMD AND A2.WORK_SEQ = 2 AND A2.DEL_YN = 'N'
WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.DEL_YN = 'N' AND A.WORK_YMD >= #{fromYmd} AND A.WORK_YMD <= #{toYmd}
AND U.USER_NM LIKE CONCAT('%', #{safeUserNm}, '%') ESCAPE '\'
ORDER BY A.WORK_YMD, A.USER_CD, A.WORK_SEQ

/* Attd08Mapper.selectAttdGpsTrail */
    SELECT
          G.GPS_ID         AS gpsId
        , G.LAT            AS lat
        , G.LON            AS lon
        , G.ACCURACY       AS accuracy
        , G.API_CALL_DATE  AS apiCallDate
        , G.API_CALL_TIME  AS apiCallTime
        , G.IS_MOCKED      AS isMocked
    FROM TB_USER_ATTD_GPS G
    WHERE G.CMPNY_CD = #{gvCmpnyCd}
      AND G.ATTD_ID  = #{attdId}
      AND EXISTS (
            SELECT 1
            FROM TB_USER_ATTD_MGMT M
            WHERE M.ATTD_ID  = #{attdId}
              AND M.CMPNY_CD = #{gvCmpnyCd}
              AND M.DEL_YN   = 'N'
          )
    ORDER BY G.API_CALL_DATE ASC, G.API_CALL_TIME ASC
